//! Property tables of the date objects (`var_dump()`, `var_export()`, `print_r()`, `json_encode()`, `(array)`,
//! `get_object_vars()`, `foreach`, `__serialize()`) against PHP 8.5.13 (`tests/vectors/dumps.json`, generated by
//! `dumps.gen.php`; regenerate with `crates/twig-date/tests/vectors/regen.sh dumps`).
//!
//! Object handles (`#N`) cannot match PHP and are normalised on both sides.

mod common;

use common::*;
use serde_json::Value as Json;
use twig_date::{DateObject, IntervalObject, TimeZoneObject, classes};
use twig_value::builtins::format::json_encode;
use twig_value::{Array, ObjectRef, Value, convert, dump};

fn make(c: &Ctx, kind: &str, arg: &str) -> ObjectRef {
    let date = |cls, s: &str| DateObject::construct(&c.ctx, cls, s.as_bytes(), None).unwrap();
    match kind {
        "dt" => date(classes::datetime(), arg),
        "dti" => date(classes::datetime_immutable(), arg),
        "tz" => TimeZoneObject::construct(&c.ctx, arg.as_bytes()).unwrap(),
        "iv" => IntervalObject::construct(&c.ctx, arg.as_bytes()).unwrap(),
        "ivs" => IntervalObject::create_from_date_string(&c.ctx, arg.as_bytes()).unwrap(),
        "diff" => {
            let (a, b) = arg.split_once('|').unwrap();
            let (a, b) = (date(classes::datetime(), a), date(classes::datetime(), b));
            obj(call(&a, "diff", vec![Value::Object(b)], &mut Vec::new()).unwrap())
        }
        other => panic!("kind {other}"),
    }
}

fn php_value(v: &Json) -> Value {
    match v {
        Json::Null => Value::Null,
        Json::Bool(b) => Value::Bool(*b),
        Json::Number(n) => Value::Int(n.as_i64().unwrap()),
        Json::String(s) => Value::from(s.as_str()),
        Json::Array(items) => Value::Array(Array::from_values(items.iter().map(php_value))),
        other => panic!("unsupported {other}"),
    }
}

/// Replaces the handle in every `object(Class)#123 (` with `#N`.
fn normalize_handles(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let b = text.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'#' && i > 0 && b[i - 1] == b')' {
            let mut j = i + 1;
            while j < b.len() && b[j].is_ascii_digit() {
                j += 1;
            }
            if j > i + 1 && text[j..].starts_with(" (") {
                out.push_str("#N");
                i = j;
                continue;
            }
        }
        out.push(b[i] as char);
        i += 1;
    }
    out
}

#[test]
fn dumps() {
    let v = load("dumps");
    let c = Ctx::new();
    c.now(1_700_000_000, 123_456);
    let mut r = Report::new("dumps");
    for case in v["dumps"].as_array().unwrap() {
        let (kind, arg) = (s(&case[0]), s(&case[1]));
        let o = make(&c, kind, arg);
        for p in case[2].as_array().unwrap() {
            o.write_property(s(&p[0]).as_bytes(), php_value(&p[1]), &mut Vec::new())
                .unwrap();
        }
        let mut diags = Vec::new();
        let val = Value::Object(o.clone());
        let what = |w: &str| format!("{w} of {kind} {arg}");
        let vd = dump::var_dump(&val, &mut diags).unwrap();
        r.eq(
            normalize_handles(&enc(vd.as_bytes())),
            s(&case[3]).to_owned(),
            || what("var_dump"),
        );
        let ve = dump::var_export(&val, &mut diags).unwrap();
        r.eq(enc(ve.as_bytes()), s(&case[4]).to_owned(), || {
            what("var_export")
        });
        let pr = dump::print_r(&val, &mut diags).unwrap();
        r.eq(enc(pr.as_bytes()), s(&case[5]).to_owned(), || {
            what("print_r")
        });
        let js = json_encode(&val, None, None, &mut diags).unwrap();
        r.eq(to_json(&js), case[6].clone(), || what("json_encode"));
        let arr = convert::to_array(&val, &mut diags).unwrap();
        r.eq(to_json(&Value::Array(arr)), case[7].clone(), || {
            what("(array)")
        });
        let gov = o.visible_properties(&mut diags).unwrap();
        let mut a = Array::new();
        for (k, v) in gov {
            a.insert(k, v);
        }
        r.eq(to_json(&Value::Array(a.clone())), case[8].clone(), || {
            what("get_object_vars")
        });
        r.eq(to_json(&Value::Array(a)), case[9].clone(), || {
            what("foreach")
        });
        let ser = call(&o, "__serialize", vec![], &mut diags).unwrap();
        r.eq(to_json(&ser), case[10].clone(), || what("__serialize"));
        r.eq(Json::from(diag_strings(&diags)), case[11].clone(), || {
            what("diagnostics")
        });
    }
    r.finish();
}
